import{_ as o,c as t,o as n,am as a}from"./chunks/framework.1_Rjriwz.js";const u=JSON.parse('{"title":"Component Grouping","description":"","frontmatter":{},"headers":[],"relativePath":"en/docs/pogget/group.md","filePath":"en/docs/pogget/group.md"}'),r={name:"en/docs/pogget/group.md"};function i(s,e,p,d,g,l){return n(),t("div",null,e[0]||(e[0]=[a('<h1 id="component-grouping" tabindex="-1">Component Grouping <a class="header-anchor" href="#component-grouping" aria-label="Permalink to &quot;Component Grouping&quot;">​</a></h1><h3 id="setting-colors" tabindex="-1">Setting Colors <a class="header-anchor" href="#setting-colors" aria-label="Permalink to &quot;Setting Colors&quot;">​</a></h3><p>Components with labels of the same color can be grouped. After grouping, adjacent components of the same color will be <strong>magnetically snapped together</strong>. Adjusting the window position, window size, etc., will affect nearby grouped windows. Grouping windows allows for easy and flexible window layouts.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If the color is set to white, it will be considered ungrouped.</p></div><p><img src="https://github.com/user-attachments/assets/64c007e1-8320-4fc5-ba8d-219abedb0f88" alt="explorer_JY4FZ6BQxd"></p><hr><h3 id="merging-and-grouping" tabindex="-1">Merging and Grouping <a class="header-anchor" href="#merging-and-grouping" aria-label="Permalink to &quot;Merging and Grouping&quot;">​</a></h3><p>After grouping, components with the same label can be merged into one large component. The merged component&#39;s position is independent of its previous position.</p><p><img src="https://github.com/user-attachments/assets/586e467b-f043-42e5-8ea8-cfdd093783ae" alt="explorer_6aIq51AM68"></p><hr><h3 id="temporarily-ungroup-if-you-need-to-adjust-the-position-or-size-of-components-after-grouping-you-can-hold-down-the-ctrl-key-while-adjusting" tabindex="-1">Temporarily Ungroup If you need to adjust the position or size of components after grouping, you can hold down the <strong>CTRL</strong> key while adjusting. <a class="header-anchor" href="#temporarily-ungroup-if-you-need-to-adjust-the-position-or-size-of-components-after-grouping-you-can-hold-down-the-ctrl-key-while-adjusting" aria-label="Permalink to &quot;Temporarily Ungroup If you need to adjust the position or size of components after grouping, you can hold down the **CTRL** key while adjusting.&quot;">​</a></h3><p><img src="https://github.com/user-attachments/assets/a6e972e4-3c35-4562-a5fb-aba19e418dee" alt="explorer_O4kWdzB9cx"></p>',12)]))}const h=o(r,[["render",i]]);export{u as __pageData,h as default};
